eck{position:absolute;left:41px;top:0;width:43px;height:47px;border:4px solid #56616a;border-bottom:0;background:#fff}.bottle-body{position:absolute;left:7px;bottom:0;width:111px;height:135px;border:4px solid #56616a;border-radius:18px 18px 25px 25px;background:#eaf8ff}.bottle-label{position:absolute;top:61px;left:17px;width:94px;text-align:center;padding:9px 2px;font-size:12px;font-weight:bold;background:#fff;border:1px solid #bcc9d2}.controls{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.controls button{border:0;border-radius:9px;padding:11px 13px;font-weight:700;cursor:pointer}.primary{background:#146fc2;color:#fff}.danger{background:#d94b4b;color:#fff}.neutral{background:#e5ebf0}.status{margin-top:12px;padding:12px;background:#f1f6f9;border-radius:10px;font-weight:600}.readings{display:grid;gap:9px}.reading{padding:11px;border:1px solid #dce4ea;border-radius:9px}.reading strong{display:block;font-size:23px;margin-top:3px}.step{padding:9px;margin-bottom:6px;border-radius:8px;background:#f3f6f8}.step.active{outline:2px solid #3288cf;background:#eef7ff}.formula{padding:13px;background:#f4f7f9;border-radius:10px}.warning{font-size:13px;color:#933f28}@media(max-width:850px){.lab-grid{grid-template-columns:1fr}.lab-scene{height:590px}.burette{left:175px}.stand{left:45px}.base{left:15px}.clamp{left:50px}.stopcock{left:186px}.tip{left:199px}.drop{left:196px}.flask{left:35px}.pipette{right:25px}}
