<?php if($isTitration): ?><div class="lab-grid"><section class="lab-card"><h2>Hands-on Titration Lab</h2><div class="lab-scene" id="scene"><div class="bench"></div><div class="stand"></div><div class="base"></div><div class="clamp"></div><div class="burette" id="burette"><div id="buretteLiquid" class="burette-liquid"></div><div class="scale">0<br>5<br>10<br>15<br>20<br>25<br>30<br>35<br>40<br>45<br>50</div></div><div id="stopcock" class="stopcock"></div><div class="tip"></div><div id="drop" class="drop"></div><div class="flask" id="flask"><div class="flask-neck"></div><div class="flask-body"><div id="solution" class="solution"></div></div><div id="swirl" class="swirl"></div></div><div class="pipette" id="pipette"><div class="pipette-bulb"></div><div class="pipette-tube"><div id="pipetteLiquid" class="pipette-liquid"></div></div><div class="pipette-tip"></div></div><div class="bottle"><div class="bottle-neck"></div><div class="bottle-body"></div><div class="bottle-label">0.100 M<br>NaOH</div></div></div><p>🖱️ <b>Drag the apparatus itself.</b> Mouse and touch are supported.</p><div class="controls"><button class="primary" onclick="action('rinse')">Rinse pipette</button><button class="primary" onclick="action('pipette')">Load/dispense HCl</button><button class="primary" onclick="action('indicator')">Add indicator</button><button class="primary" onclick="action('fill')">Fill burette</button><button class="primary" onclick="action('initial')">Record initial</button><button class="primary" onclick="action('swirl')">Swirl flask</button><button class="danger" onclick="action('stop')">Stop flow</button><button class="neutral" onclick="action('reset')">New trial</button></div><div id="status" class="status">Rinse the pipette first.</div></section>
<aside class="lab-card"><h2>Live state</h2><div class="readings"><div class="reading">Burette<strong><span id="reading">0.00</span> mL</strong></div><div class="reading">Delivered<strong><span id="delivered">0.00</span> mL</strong></div><div class="reading">Pipette<strong id="pipetteState">Empty</strong></div><div class="reading">Indicator<strong id="indicatorState">Not added</strong></div><div class="reading">Reaction<strong id="reaction">Acidic / colourless</strong></div></div><hr><h3>Procedure</h3><div class="step active">1. Rinse pipette</div><div class="step">2. Transfer 25.00 mL HCl</div><div class="step">3. Add phenolphthalein</div><div class="step">4. Prepare NaOH burette</div><div class="step">5. Record initial reading</div><div class="step">6. Titrate with controlled flow</div><div class="step">7. Stop at permanent faint pink</div><h3>Calculation</h3><div class="formula">C₁V₁ = C₂V₂<br><br>HCl: 0.100 M × 25.00 mL<br>NaOH: 0.100 M<br><b>Expected titre ≈ 25.00 mL</b></div><p class="warning">Too much titrant near the endpoint produces an overshoot and an invalid trial.</p></aside></div>
<script>
const S={step:1,r:0,i:null,rinsed:false,acid:false,indicator:false,filled:false,flow:null,over:false,pipette:false};const $=x=>document.getElementById(x);function say(x){$('status').textContent=x}function draw(){let d=S.i===null?0:Math.max(0,S.r-S.i);$('reading').textContent=S.r.toFixed(2);$('delivered').textContent=d.toFixed(2);$('buretteLiquid').style.height=Math.max(4,100-S.r/50*100)+'%';$('pipetteLiquid').style.height=S.pipette?'155px':'0';$('pipetteState').textContent=S.pipette?'25.00 mL HCl loaded':S.acid?'HCl delivered — empty':'Empty';$('indicatorState').textContent=S.indicator?'Phenolphthalein':'Not added';$('reaction').textContent=S.over?'Overshot — invalid':S.r>=24.98?'Endpoint — faint pink':'Acidic / colourless';$('solution').className='solution '+(S.over?'overshot':S.r>=24.98?'endpoint':'');$('stopcock').classList.toggle('open',!!S.flow);document.querySelectorAll('.step').forEach((x,n)=>x.classList.toggle('active',n+1===S.step))}
function action(a){if(a==='reset'){if(S.flow)clearInterval(S.flow);Object.assign(S,{step:1,r:0,i:null,rinsed:false,acid:false,indicator:false,filled:false,flow:null,over:false,pipette:false});say('New trial started.');draw();return}if(a==='rinse'){S.rinsed=true;S.step=2;say('Pipette rinsed and ready.');draw();return}if(a==='pipette'){if(!S.rinsed)return say('Rinse the pipette first.');if(!S.pipette&&!S.acid){S.pipette=true;S.step=2;say('Pipette loaded with 25.00 mL HCl. Press again after moving it to the flask to dispense.')}else if(S.pipette){S.pipette=false;S.acid=true;S.step=3;say('25.00 mL HCl dispensed into the flask.')}draw();return}if(a==='indicator'){if(!S.acid)return say('Transfer HCl first.');S.indicator=true;S.step=4;say('Phenolphthalein added; acidic solution remains colourless.');draw();return}if(a==='fill'){if(!S.indicator)return say('Add the indicator first.');S.filled=true;S.r=0;S.step=5;say('Burette filled with 0.100 M NaOH.');draw();return}if(a==='initial'){if(!S.filled)return say('Fill the burette first.');S.i=S.r;S.step=6;say('Initial reading recorded. Open the stopcock.');draw();return}if(a==='swirl'){$('swirl').classList.toggle('swirling');say('Flask is swirling; incoming titrant mixes through the sample.');return}if(a==='stop'&&S.flow){clearInterval(S.flow);S.flow=null;say('Flow stopped at '+S.r.toFixed(2)+' mL.');draw();return}}
$('stopcock').onclick=()=>{if(S.i===null)return say('Record the initial reading first.');if(S.flow){clearInterval(S.flow);S.flow=null;draw();return}S.flow=setInterval(()=>{S.r+=S.r>=22?.05:.20;let d=$('drop');d.classList.remove('fall');void d.offsetWidth;d.classList.add('fall');if(S.r>=24.98){if(S.r>=25.25){S.over=true;say('Overshot! The endpoint colour is too strong. Repeat the trial.')}else say('Permanent faint pink endpoint reached.');clearInterval(S.flow);S.flow=null;S.step=7}draw()},180)};
function drag(el){let down=false,sx=0,sy=0,ox=0,oy=0;el.addEventListener('pointerdown',e=>{down=true;sx=e.clientX;sy=e.clientY;let r=el.getBoundingClientRect(),s=$('scene').getBoundingClientRect();ox=r.left-s.left;oy=r.top-s.top;el.classList.add('dragging');el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!down)return;let s=$('scene').getBoundingClientRect();el.style.left=Math.max(4,Math.min(s.width-el.offsetWidth-4,ox+e.clientX-sx))+'px';el.style.top=Math.max(4,Math.min(s.height-el.offsetHeight-4,oy+e.clientY-sy))+'px';el.style.right='auto';el.style.bottom='auto'});el.addEventListener('pointerup',()=>{down=false;el.classList.remove('dragging')})}drag($('burette'));drag($('flask'));drag($('pipette'));draw();
</script>
